// El webhook entrega el payload en $json.body (n8n lo anida bajo 'body'
// cuando el Content-Type es application/json). Aceptamos ambos por robustez.
const raw = $json || {};
const d = raw.body || raw;
const provider = (d.email_provider || 'outlook').toLowerCase();

// $env.* está bloqueado por N8N_BLOCK_ENV_ACCESS_IN_NODE. El fallback
// del callback va hardcoded. El backend puede sobreescribir enviando 'callbackUrl'.
return {
  requestId: d.requestId || '',
  apiKey: d.apiKey || '',
  empresaId: d.empresaId || null,
  startDate: d.startDate || '',
  endDate: d.endDate || '',
  email: d.email || '',
  email_provider: provider,
  credential_email_id: d.credential_email_id || '',
  // OAuth multi-tenant: access_token refrescado por el backend en cada búsqueda.
  // Los nodos HTTP Gmail/Outlook lo usan como Bearer token en vez de una
  // Predefined Credential guardada en n8n.
  gmail_access_token: d.gmail_access_token || '',
  gmail_email: d.gmail_email || '',
  outlook_access_token: d.outlook_access_token || '',
  outlook_email: d.outlook_email || '',
  // Gemini API key resuelta (per-tenant override → global fallback).
  gemini_api_key: d.gemini_api_key || '',
  callbackUrl: d.callbackUrl || 'http://127.0.0.1:8000/api/asistente/callback/search-results'
};

// Graph responde { value: [ ...messages ] } en un solo item. Lo expandimos
// en items individuales para que 'Normalizar Adjuntos' procese cada correo
// con la misma lógica que las otras ramas.
const raw = $json || {};
const messages = raw.value || raw || [];
if (!Array.isArray(messages)) {
  return [{ empty: true, error: 'Respuesta Graph inesperada', raw: JSON.stringify(raw).slice(0, 500) }];
}
if (messages.length === 0) {
  return [{ empty: true }];
}
return messages;

// Gmail API responde { messages: [{ id, threadId }, ...] } en 1 solo item.
// Expandimos a items individuales para que el siguiente Get de mensaje
// procese cada uno por separado.
const raw = $json || {};
const messages = raw.messages || [];
if (!Array.isArray(messages) || messages.length === 0) {
  const ctx = $('Extraer Contexto').first().json;
  return [{ empty: true, ...ctx }];
}
return messages;

// Recibe mensajes Gmail con payload.headers y payload.parts.
// Emite 1 item por cada PDF/ZIP adjunto, con messageId + attachmentId +
// metadata (sender, subject, date) + contexto tenant. NO descarga el binario
// (eso lo hace el siguiente HTTP Request a Gmail API).
const ctx = $('Extraer Contexto').first().json;
const results = [];

const walk = (parts, out) => {
  for (const p of (parts || [])) {
    if (p.filename && p.body?.attachmentId) {
      out.push({
        name: p.filename,
        mimeType: p.mimeType,
        attachmentId: p.body.attachmentId,
        size: p.body.size
      });
    }
    if (p.parts) walk(p.parts, out);
  }
};

for (const item of $input.all()) {
  const email = item.json || {};
  const headers = email.payload?.headers || [];
  const subject = headers.find(h => h.name === 'Subject')?.value || 'Sin asunto';
  const from = headers.find(h => h.name === 'From')?.value || '';
  const date = headers.find(h => h.name === 'Date')?.value || '';
  const messageId = email.id;

  const attachments = [];
  walk(email.payload?.parts, attachments);

  for (const att of attachments) {
    const ext = (att.name.split('.').pop() || '').toLowerCase();
    if (ext !== 'pdf' && ext !== 'zip') continue;

    results.push({
      messageId,
      attachmentId: att.attachmentId,
      filename: att.name,
      mimeType: att.mimeType,
      size: att.size,
      sender: from,
      subject,
      date,
      provider: 'gmail',
      ...ctx
    });
  }
}

if (results.length === 0) {
  return [{ empty: true, ...ctx }];
}
return results;

// Toma el metadata previo (Extraer Metadata Gmail) y el response del
// HTTP Request (data en base64 URL-safe). Convierte a base64 estándar y
// emite el item final con content_base64 + ctx.
//
// Uso $itemIndex + .all() para acceder al metadata correspondiente al
// item actual — el pairedItem se rompe cuando un HTTP Request procesa 1×N,
// pero el orden de items se preserva.
const idx = $itemIndex;
const allMeta = $('Extraer Metadata Gmail').all();
const meta = allMeta[idx]?.json || {};
const raw = $json || {};
const urlSafeB64 = raw.data || '';

// Base64 URL-safe → estándar: reemplaza -/_ por +// y añade padding si falta
let b64 = urlSafeB64.replace(/-/g, '+').replace(/_/g, '/');
b64 = b64 + '='.repeat((4 - b64.length % 4) % 4);

return {
  filename: meta.filename,
  size: raw.size || meta.size,
  date: meta.date,
  sender: meta.sender,
  subject: meta.subject,
  contentType: meta.mimeType,
  storage_path: meta.filename,
  messageId: meta.messageId,
  attachmentId: meta.attachmentId,
  sourceId: meta.messageId + '::' + meta.filename,
  provider: 'gmail',
  content_base64: b64,
  // Contexto tenant
  requestId: meta.requestId,
  apiKey: meta.apiKey,
  empresaId: meta.empresaId,
  email: meta.email,
  email_provider: meta.email_provider,
  credential_email_id: meta.credential_email_id,
  callbackUrl: meta.callbackUrl,
  startDate: meta.startDate,
  endDate: meta.endDate
};

// Normaliza la salida de cualquiera de los providers a un esquema único.
// Cada item de entrada es un correo; emitimos un item por cada adjunto PDF/ZIP.
// Incluye el contenido base64 del adjunto para que el backend pueda procesarlo
// sin necesidad de descargarlo por separado.
const ctx = $('Extraer Contexto').first().json;
const results = [];

for (const item of $input.all()) {
  const email = item.json || {};
  let subject, from, date, attachments, messageId, provider;

  // Outlook Graph (detectar por conversationId, único de MS Graph)
  if (email.conversationId) {
    provider = 'outlook';
    subject = email.subject || 'Sin asunto';
    from = email.from?.emailAddress?.address
        || email.from?.address
        || (typeof email.from === 'string' ? email.from : '')
        || '';
    date = email.receivedDateTime || '';
    attachments = email.attachments || [];
    messageId = email.id;
  }
  // Gmail
  else if (email.payload?.headers) {
    provider = 'gmail';
    const headers = email.payload.headers || [];
    subject = headers.find(h => h.name === 'Subject')?.value || 'Sin asunto';
    from = headers.find(h => h.name === 'From')?.value || '';
    date = headers.find(h => h.name === 'Date')?.value || '';
    const walk = (parts) => {
      const out = [];
      for (const p of (parts || [])) {
        if (p.filename && p.body?.attachmentId) {
          out.push({ name: p.filename, mimeType: p.mimeType, attachmentId: p.body.attachmentId, size: p.body.size });
        }
        if (p.parts) out.push(...walk(p.parts));
      }
      return out;
    };
    attachments = walk(email.payload.parts);
    messageId = email.id;
  }
  else {
    // Formato desconocido → salta
    continue;
  }

  for (const att of attachments) {
    const name = att.name || att.filename || 'archivo';
    const ext = (name.split('.').pop() || '').toLowerCase();
    if (ext !== 'pdf' && ext !== 'zip') continue;

    // Outlook con $expand=attachments trae contentBytes ya en base64.
    // Gmail requiere descarga aparte con attachmentId — la haría el backend.
    const contentB64 = att.contentBytes
      || att.content
      || att.data
      || '';

    results.push({
      filename: name,
      size: att.size || (contentB64 ? Math.floor(contentB64.length * 3 / 4) : 0),
      date,
      sender: from,
      subject,
      contentType: att.contentType || att.mimeType || '',
      storage_path: name,
      messageId,
      attachmentId: att.id || att.attachmentId || '',
      sourceId: messageId + '::' + name,
      provider,
      content_base64: contentB64,
      ...ctx
    });
  }
}

if (results.length === 0) {
  return [{ empty: true, ...ctx }];
}
return results;
